BEGIN;

CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path = extensions, pg_temp, public;
SELECT no_plan();

-- Fixtures are synthetic and the entire file rolls back without custom SQL helpers.
CREATE TEMPORARY TABLE planning_ids (name text PRIMARY KEY, id uuid NOT NULL DEFAULT gen_random_uuid()) ON COMMIT DROP;
INSERT INTO planning_ids (name) VALUES ('workspace'), ('other_workspace'), ('book'), ('other_book'), ('foreign_book'), ('cash'), ('liability'), ('investment'), ('other_account'), ('foreign_account'), ('person'), ('foreign_person'), ('expense_category'), ('income_category'), ('other_category'), ('second_expense_category'), ('expense'), ('income'), ('group'), ('rule'), ('rule_line'), ('plan'), ('plan_line'), ('allocation'), ('debt'), ('goal'), ('earmark'), ('asset'), ('valuation'), ('batch'), ('row'), ('summary'), ('coverage');

INSERT INTO core.workspaces (id, name, timezone) VALUES
  ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), 'Planning native constraint fixture', 'America/Mexico_City'),
  ((SELECT id FROM pg_temp.planning_ids WHERE name = 'other_workspace'), 'Other native constraint fixture', 'UTC');
INSERT INTO core.people (id, workspace_id, display_name) VALUES
  ((SELECT id FROM pg_temp.planning_ids WHERE name = 'person'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), 'Synthetic self'),
  ((SELECT id FROM pg_temp.planning_ids WHERE name = 'foreign_person'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'other_workspace'), 'Other synthetic person');
INSERT INTO finance.books (id, workspace_id, name, currency, minor_unit) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), 'Native book', 'MXN', 2);
INSERT INTO finance.books (id, workspace_id, name, currency, minor_unit) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'other_book'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), 'Other native book', 'MXN', 2);
INSERT INTO finance.books (id, workspace_id, name, currency, minor_unit) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'foreign_book'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'other_workspace'), 'Foreign native book', 'USD', 2);
INSERT INTO finance.accounts (id, workspace_id, book_id, currency, name, opening_balance) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'cash'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Legacy account', 1000);
INSERT INTO finance.accounts (id, workspace_id, book_id, currency, name, opening_balance, account_kind, opening_balance_on) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'liability'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Synthetic loan', -500, 'loan', DATE '2026-01-01');
INSERT INTO finance.accounts (id, workspace_id, book_id, currency, name, opening_balance, account_kind, opening_balance_on) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'investment'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Synthetic investment', 1000, 'investment', DATE '2026-01-01');
INSERT INTO finance.accounts (id, workspace_id, book_id, currency, name, opening_balance) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'other_account'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'other_book'), 'MXN', 'Other book account', 0);
INSERT INTO finance.accounts (id, workspace_id, book_id, currency, name, opening_balance) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'foreign_account'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'other_workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'foreign_book'), 'USD', 'Foreign account', 0);
INSERT INTO finance.categories (id, workspace_id, book_id, currency, name, kind) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'expense_category'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Food', 'expense');
INSERT INTO finance.categories (id, workspace_id, book_id, currency, name, kind) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'second_expense_category'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Housing', 'expense');
INSERT INTO finance.categories (id, workspace_id, book_id, currency, name, kind) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'income_category'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Salary', 'income');
INSERT INTO finance.categories (id, workspace_id, book_id, currency, name, kind) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'other_category'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'other_book'), 'MXN', 'Other category', 'expense');
INSERT INTO finance.transactions (id, workspace_id, book_id, currency, kind, amount, source_account_id, occurred_on, description, request_id) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'expense'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'expense', 100, (SELECT id FROM pg_temp.planning_ids WHERE name = 'cash'), DATE '2026-01-10', 'Synthetic expense', gen_random_uuid());
INSERT INTO finance.transactions (id, workspace_id, book_id, currency, kind, amount, destination_account_id, occurred_on, description, request_id) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'income'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'income', 500, (SELECT id FROM pg_temp.planning_ids WHERE name = 'cash'), DATE '2026-01-10', 'Synthetic income', gen_random_uuid());
INSERT INTO finance.transaction_groups (id, workspace_id, book_id, currency, request_id, description) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'group'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', gen_random_uuid(), 'Synthetic component group');
INSERT INTO finance.transaction_classifications (workspace_id, book_id, currency, transaction_id, kind, category_id, group_id, group_position) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense'), 'expense', (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense_category'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'group'), 1);
INSERT INTO finance.recurring_rules (id, workspace_id, book_id, currency, name, interval, start_period, due_day, short_month_policy) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'rule'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Synthetic monthly rule', 'monthly', DATE '2026-01-01', 31, 'last_day');
INSERT INTO finance.recurring_rule_lines (id, workspace_id, book_id, currency, rule_id, line_number, kind, amount, category_id) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'rule_line'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'rule'), 1, 'expense', 100, (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense_category'));
INSERT INTO finance.debt_details (id, workspace_id, book_id, currency, account_id, creditor) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'debt'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'liability'), 'Synthetic known creditor');
INSERT INTO finance.planned_items (id, workspace_id, book_id, currency, name, period_start, rule_id, rule_version, debt_account_id, quoted_total) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'plan'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Synthetic plan', DATE '2026-01-01', (SELECT id FROM pg_temp.planning_ids WHERE name = 'rule'), 1, (SELECT id FROM pg_temp.planning_ids WHERE name = 'liability'), 100);
INSERT INTO finance.planned_item_lines (id, workspace_id, book_id, currency, planned_item_id, line_number, kind, amount, category_id, source_account_id) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'plan_line'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'plan'), 1, 'expense', 100, (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense_category'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'cash'));
INSERT INTO finance.planned_item_allocations (id, workspace_id, book_id, currency, planned_item_id, planned_item_line_id, transaction_id, kind, amount) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'allocation'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'plan'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'plan_line'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense'), 'expense', 50);
INSERT INTO finance.savings_goals (id, workspace_id, book_id, currency, name, target_amount, target_on, person_id) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'goal'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Synthetic goal', 2000, DATE '2027-01-01', (SELECT id FROM pg_temp.planning_ids WHERE name = 'person'));
INSERT INTO finance.assets (id, workspace_id, book_id, currency, name, identity_text, ownership_text, person_id) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'asset'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Synthetic asset', 'fixture-property-identity', 'Accepted sole ownership', (SELECT id FROM pg_temp.planning_ids WHERE name = 'person'));
INSERT INTO finance.asset_valuations (id, workspace_id, book_id, currency, account_id, valued_on, amount, source) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'valuation'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'investment'), DATE '2026-01-01', 1100, 'Synthetic accepted observation');
INSERT INTO finance.goal_allocations (id, workspace_id, book_id, currency, goal_id, account_id, amount, funding_basis, valuation_id) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'earmark'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'goal'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'investment'), 100, 'valuation', (SELECT id FROM pg_temp.planning_ids WHERE name = 'valuation'));
INSERT INTO finance.import_batches (id, workspace_id, book_id, currency, actor_user_id, workbook_id, source_version, captured_at, manifest, review_digest) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'batch'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', gen_random_uuid(), 'synthetic-workbook', 'synthetic-version-1', TIMESTAMPTZ '2026-01-31 12:00:00+00', '{}'::jsonb, decode(repeat('11', 32), 'hex'));
INSERT INTO finance.import_rows (id, workspace_id, book_id, currency, batch_id, row_number, workbook_id, sheet_id, source_cell, period_start, source_key, source_digest, source_snapshot, role, kind, amount, category_id, accepted) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'row'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'batch'), 1, 'synthetic-workbook', 111111100, 'C17', DATE '2026-01-01', 'synthetic-workbook:111111100:C17:2026-01-01', decode(repeat('22', 32), 'hex'), '{"label":"Synthetic monthly-only fixture"}'::jsonb, 'actual_summary', 'expense', 100, (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense_category'), true);
INSERT INTO finance.monthly_summaries (id, workspace_id, book_id, currency, period_start, kind, amount, category_id, import_row_id) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'summary'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', DATE '2026-01-01', 'expense', 100, (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense_category'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'row'));
UPDATE finance.import_rows SET result_summary_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'summary'), consumed_at = now() WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'row');
INSERT INTO finance.report_coverage (id, workspace_id, book_id, currency, period_start, kind, category_id, authority, reviewed_detail_count, reviewed_detail_digest) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'coverage'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', DATE '2026-01-01', 'expense', (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense_category'), 'summary', 1, decode(repeat('33', 32), 'hex'));

SELECT ok((SELECT account_kind = 'unknown' AND opening_balance_on IS NULL AND opening_balance = 1000 FROM finance.accounts WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'cash')), 'Legacy account defaults preserve unknown kind/date and the original opening amount');
SELECT ok((SELECT credit_limit IS NULL AND annual_rate IS NULL AND minimum_payment IS NULL AND statement_day IS NULL AND due_day IS NULL AND payment_terms IS NULL FROM finance.debt_details WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'debt')), 'Unknown debt facts remain null rather than generated terms');
SELECT ok((SELECT due_on IS NULL AND components_resolved AND canceled_at IS NULL FROM finance.planned_items WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'plan')), 'A month-precision plan does not invent a due day');
SELECT is((SELECT count(*) FROM finance.transactions WHERE workspace_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace')), 2::bigint, 'Plans, goals, valuations, summaries and coverage add no ledger movements');

SELECT ok(has_table_privilege('impulso_backend', c.oid, 'SELECT') AND has_table_privilege('impulso_backend', c.oid, 'INSERT') AND NOT has_table_privilege('impulso_backend', c.oid, 'UPDATE,DELETE,TRUNCATE,TRIGGER'), 'The backend has bounded read/insert and no broad update/delete for ' || c.relname)
FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE n.nspname = 'finance' AND c.relkind = 'r' AND c.relname <> 'files'
ORDER BY c.relname;

SELECT ok(NOT has_column_privilege('impulso_backend', 'finance.transactions', column_name, 'UPDATE'), 'Posted transaction ' || column_name || ' remains immutable to the backend')
FROM (VALUES ('id'), ('workspace_id'), ('book_id'), ('kind'), ('amount'), ('currency'), ('source_account_id'), ('destination_account_id'), ('beneficiary_person_id'), ('occurred_on'), ('description'), ('request_id'), ('replaces_transaction_id')) AS columns(column_name);
SELECT ok(NOT has_column_privilege('impulso_backend', 'finance.transaction_classifications', column_name, 'UPDATE'), 'Stored group membership ' || column_name || ' is immutable to the backend')
FROM (VALUES ('transaction_id'), ('kind'), ('group_id'), ('group_position')) AS columns(column_name);
SELECT ok(NOT has_column_privilege('impulso_backend', 'finance.import_rows', column_name, 'UPDATE'), 'Frozen import row ' || column_name || ' is immutable to the backend')
FROM (VALUES ('workbook_id'), ('sheet_id'), ('source_cell'), ('period_start'), ('source_key'), ('source_digest'), ('source_snapshot'), ('mapping'), ('role'), ('amount'), ('accepted')) AS columns(column_name);

SELECT throws_ok(statement, expected_state, NULL::text, description)
FROM (VALUES
  ($sql$UPDATE finance.accounts SET account_kind = 'guessed_card' WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'cash')$sql$, '23514', 'Unknown account types are rejected'),
  ($sql$UPDATE finance.accounts SET opening_balance_on = 'infinity'::date WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'cash')$sql$, '23514', 'An opening boundary must be a concrete supported date'),
  ($sql$INSERT INTO finance.categories (workspace_id, book_id, currency, name, kind) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Invalid category', 'transfer')$sql$, '23514', 'A transfer cannot be an income or expense category'),
  ($sql$UPDATE finance.transaction_classifications SET category_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'income_category') WHERE transaction_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense')$sql$, '23503', 'Category kind must match the immutable transaction kind'),
  ($sql$UPDATE finance.transaction_classifications SET category_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'other_category') WHERE transaction_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense')$sql$, '23503', 'A classification cannot cross books'),
  ($sql$UPDATE finance.transaction_classifications SET group_position = NULL WHERE transaction_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense')$sql$, '23514', 'A group member must retain a concrete bounded position'),
  ($sql$UPDATE finance.transaction_classifications SET group_position = 11 WHERE transaction_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense')$sql$, '23514', 'A group cannot contain an eleventh component'),
  ($sql$INSERT INTO finance.transaction_classifications (workspace_id, book_id, currency, transaction_id, kind, group_id, group_position) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'income'), 'income', (SELECT id FROM pg_temp.planning_ids WHERE name = 'group'), 1)$sql$, '23505', 'One group position cannot be reused by another component'),
  ($sql$INSERT INTO finance.transaction_classifications (workspace_id, book_id, currency, transaction_id, kind) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense'), 'expense')$sql$, '23505', 'A transaction has only one current classification relation'),
  ($sql$INSERT INTO finance.recurring_rules (workspace_id, book_id, currency, name, interval, start_period) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Invalid month', 'monthly', DATE '2026-01-02')$sql$, '23514', 'A recurrence begins at month precision'),
  ($sql$UPDATE finance.recurring_rules SET due_day = 32 WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'rule')$sql$, '23514', 'A due day cannot exceed the calendar day range'),
  ($sql$UPDATE finance.recurring_rules SET short_month_policy = NULL WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'rule')$sql$, '23514', 'A due day requires an explicit short-month policy'),
  ($sql$UPDATE finance.recurring_rules SET end_period = DATE '2025-12-01' WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'rule')$sql$, '23514', 'A recurrence cannot end before it starts'),
  ($sql$INSERT INTO finance.planned_items (workspace_id, book_id, currency, name, period_start, rule_id, rule_version) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Duplicate occurrence', DATE '2026-01-01', (SELECT id FROM pg_temp.planning_ids WHERE name = 'rule'), 1)$sql$, '23505', 'One recurrence period cannot be materialized twice'),
  ($sql$INSERT INTO finance.planned_items (workspace_id, book_id, currency, name, period_start, components_resolved) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Missing quoted amount', DATE '2026-01-01', false)$sql$, '23514', 'Unresolved components require an accepted quoted total'),
  ($sql$UPDATE finance.planned_items SET quoted_total = 0 WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'plan')$sql$, '23514', 'Quoted payment totals must be positive'),
  ($sql$UPDATE finance.planned_item_lines SET source_account_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'other_account') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'plan_line')$sql$, '23503', 'A planned line cannot use another book''s account'),
  ($sql$UPDATE finance.planned_item_lines SET category_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'income_category') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'plan_line')$sql$, '23503', 'Planned components preserve category kind'),
  ($sql$UPDATE finance.planned_item_lines SET beneficiary_person_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'foreign_person') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'plan_line')$sql$, '23503', 'Planned attribution cannot cross workspaces'),
  ($sql$UPDATE finance.planned_item_allocations SET transaction_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'income') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'allocation')$sql$, '23503', 'A settlement must reference an actual component of the same kind'),
  ($sql$UPDATE finance.planned_item_allocations SET currency = 'USD' WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'allocation')$sql$, '23503', 'Settlement currency cannot cross the book boundary'),
  ($sql$UPDATE finance.planned_item_allocations SET amount = 'NaN'::numeric WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'allocation')$sql$, '23514', 'A settlement amount cannot be NaN'),
  ($sql$UPDATE finance.debt_details SET account_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'other_account') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'debt')$sql$, '23503', 'Debt metadata cannot cross books'),
  ($sql$UPDATE finance.debt_details SET credit_limit = -1 WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'debt')$sql$, '23514', 'A known credit limit cannot be negative'),
  ($sql$UPDATE finance.debt_details SET annual_rate = 'NaN'::numeric WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'debt')$sql$, '23514', 'A stated rate must be finite'),
  ($sql$UPDATE finance.savings_goals SET target_amount = 0 WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'goal')$sql$, '23514', 'Savings targets must be positive'),
  ($sql$UPDATE finance.savings_goals SET person_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'foreign_person') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'goal')$sql$, '23503', 'Goal attribution cannot cross workspaces'),
  ($sql$UPDATE finance.goal_allocations SET account_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'cash') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'earmark')$sql$, '23503', 'A valuation-backed earmark must reference that same valued account'),
  ($sql$UPDATE finance.goal_allocations SET funding_basis = 'ledger' WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'earmark')$sql$, '23514', 'Ledger earmarks cannot silently retain a valuation reference'),
  ($sql$UPDATE finance.goal_allocations SET valuation_id = NULL WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'earmark')$sql$, '23514', 'Valuation earmarks require an explicit accepted valuation'),
  ($sql$UPDATE finance.assets SET person_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'foreign_person') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'asset')$sql$, '23503', 'Asset ownership attribution cannot cross workspaces'),
  ($sql$UPDATE finance.asset_valuations SET asset_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'asset') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'valuation')$sql$, '23514', 'A valuation cannot target an account and manual asset together'),
  ($sql$UPDATE finance.asset_valuations SET account_id = NULL WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'valuation')$sql$, '23514', 'A valuation must target exactly one holding'),
  ($sql$UPDATE finance.asset_valuations SET amount = -1 WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'valuation')$sql$, '23514', 'Valuations cannot be negative'),
  ($sql$UPDATE finance.asset_valuations SET amount = 'NaN'::numeric WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'valuation')$sql$, '23514', 'Valuations cannot be NaN'),
  ($sql$INSERT INTO finance.asset_valuations (workspace_id, book_id, currency, account_id, valued_on, amount, source) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'investment'), DATE '2026-01-01', 1000, 'Unreviewed duplicate')$sql$, '23505', 'A holding cannot have two active valuations on one date'),
  ($sql$UPDATE finance.import_batches SET review_digest = decode('00','hex') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'batch')$sql$, '23514', 'Reviewed import digests must contain exactly 32 bytes'),
  ($sql$UPDATE finance.import_rows SET workbook_id = 'another-workbook' WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'row')$sql$, '23503', 'A frozen row must retain its batch workbook'),
  ($sql$UPDATE finance.import_rows SET result_transaction_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'row')$sql$, '23514', 'A consumed source cannot have multiple financial result kinds'),
  ($sql$UPDATE finance.import_rows SET result_summary_id = NULL WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'row')$sql$, '23514', 'Consumed summaries require their scoped result link'),
  ($sql$UPDATE finance.import_rows SET role = 'reference' WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'row')$sql$, '23514', 'Reference-only source rows cannot consume financial identity'),
  ($sql$UPDATE finance.import_rows SET source_cell = 'C0' WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'row')$sql$, '23514', 'Source identity must use a concrete bounded A1 cell'),
  ($sql$UPDATE finance.monthly_summaries SET period_start = DATE '2026-01-10' WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'summary')$sql$, '23514', 'A monthly summary cannot invent day precision'),
  ($sql$UPDATE finance.monthly_summaries SET category_id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'income_category') WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'summary')$sql$, '23503', 'A summary category must match its income or expense kind'),
  ($sql$UPDATE finance.monthly_summaries SET amount = -1 WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'summary')$sql$, '23514', 'Actual monthly summary magnitudes cannot be negative'),
  ($sql$INSERT INTO finance.report_coverage (workspace_id, book_id, currency, period_start, kind, category_id, authority, reviewed_detail_count) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', DATE '2026-01-01', 'expense', (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense_category'), 'detail', 1)$sql$, '23505', 'One coverage key cannot authorize detail and summary independently'),
  ($sql$UPDATE finance.report_coverage SET authority = 'both' WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'coverage')$sql$, '23514', 'Coverage cannot silently add detail and summary'),
  ($sql$INSERT INTO finance.import_rows (workspace_id, book_id, currency, batch_id, row_number, workbook_id, sheet_id, source_cell, period_start, source_key, source_digest, source_snapshot, role, kind, amount, accepted, result_transaction_id, consumed_at) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'batch'), 2, 'synthetic-workbook', 111111100, 'C17', DATE '2026-01-01', 'a-different-caller-key', decode(repeat('44', 32), 'hex'), '{}'::jsonb, 'actual_detail', 'expense', 100, true, (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense'), now())$sql$, '23505', 'Stable source consumption remains unique across roles, caller keys and changed source hashes'),
  ($sql$INSERT INTO finance.import_rows (workspace_id, book_id, currency, batch_id, row_number, workbook_id, sheet_id, source_cell, period_start, source_key, source_digest, source_snapshot, role, kind, amount, accepted, result_transaction_id, consumed_at) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'batch'), 2, 'synthetic-workbook', 111111100, 'D17', DATE '2026-01-01', 'a-different-caller-key', decode(repeat('44', 32), 'hex'), '{}'::jsonb, 'unknown', 'expense', 100, true, (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense'), now())$sql$, '23514', 'Unresolved rows cannot consume source identity')
) AS cases(statement, expected_state, description);

SELECT lives_ok($sql$INSERT INTO finance.budgets (workspace_id, book_id, currency, name, starts_on, ends_on, amount) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Whole-book budget', DATE '2026-01-01', DATE '2026-02-01', 1000)$sql$, 'A whole-book budget remains valid');
SELECT lives_ok($sql$INSERT INTO finance.budgets (workspace_id, book_id, currency, name, category_id, starts_on, ends_on, amount) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Food budget', (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense_category'), DATE '2026-01-01', DATE '2026-02-01', 500)$sql$, 'A category budget can share the whole-book interval');
SELECT lives_ok($sql$INSERT INTO finance.budgets (workspace_id, book_id, currency, name, category_id, starts_on, ends_on, amount) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Housing budget', (SELECT id FROM pg_temp.planning_ids WHERE name = 'second_expense_category'), DATE '2026-01-01', DATE '2026-02-01', 600)$sql$, 'Different category budgets can share an interval');
