SELECT lives_ok($sql$INSERT INTO finance.planned_items (workspace_id, book_id, currency, name, period_start, quoted_total, components_resolved) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', 'Unresolved installment', DATE '2026-02-01', 900, false)$sql$, 'An unresolved installment retains its accepted positive quoted total without invented lines');
SELECT lives_ok($sql$INSERT INTO finance.asset_valuations (workspace_id, book_id, currency, asset_id, valued_on, amount, source) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'asset'), DATE '2026-01-01', 0, 'Explicit known zero fixture')$sql$, 'A known zero manual valuation is distinct from missing valuation');
SELECT lives_ok($sql$UPDATE finance.recurring_rule_lines SET retired_at = now() WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'rule_line')$sql$, 'Old recurrence lines can be retired without deleting history');
SELECT lives_ok($sql$INSERT INTO finance.recurring_rule_lines (workspace_id, book_id, currency, rule_id, line_number, kind, amount) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'rule'), 1, 'expense', 200)$sql$, 'An explicitly revised template can reuse a retired position');
