SELECT lives_ok($sql$UPDATE finance.import_rows SET retired_at = now() WHERE id = (SELECT id FROM pg_temp.planning_ids WHERE name = 'row')$sql$, 'Reviewed source replacement can retain retired provenance');
SELECT lives_ok($sql$INSERT INTO finance.import_rows (workspace_id, book_id, currency, batch_id, row_number, workbook_id, sheet_id, source_cell, period_start, source_key, source_digest, source_snapshot, role, kind, amount, accepted, result_transaction_id, consumed_at, replaces_row_id) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'batch'), 2, 'synthetic-workbook', 111111100, 'C17', DATE '2026-01-01', 'a-different-caller-key', decode(repeat('44', 32), 'hex'), '{}'::jsonb, 'actual_detail', 'expense', 100, true, (SELECT id FROM pg_temp.planning_ids WHERE name = 'expense'), now(), (SELECT id FROM pg_temp.planning_ids WHERE name = 'row'))$sql$, 'An explicit replacement can consume the same source only after retiring its predecessor');
