SELECT lives_ok($sql$INSERT INTO finance.import_rows (workspace_id, book_id, currency, batch_id, row_number, workbook_id, sheet_id, source_cell, period_start, source_key, source_digest, source_snapshot, role, kind, amount, accepted, replaces_row_id) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'batch'), 3, 'synthetic-workbook', 111111100, 'C17', DATE '2026-01-01', 'draft-preview-3', decode(repeat('55', 32), 'hex'), '{}'::jsonb, 'actual_detail', 'expense', 100, true, (SELECT id FROM pg_temp.planning_ids WHERE name = 'row'))$sql$, 'A new uncommitted reviewed preview does not reserve the prior source replacement');
SELECT lives_ok($sql$INSERT INTO finance.import_rows (workspace_id, book_id, currency, batch_id, row_number, workbook_id, sheet_id, source_cell, period_start, source_key, source_digest, source_snapshot, role, kind, amount, accepted, replaces_row_id) VALUES ((SELECT id FROM pg_temp.planning_ids WHERE name = 'workspace'), (SELECT id FROM pg_temp.planning_ids WHERE name = 'book'), 'MXN', (SELECT id FROM pg_temp.planning_ids WHERE name = 'batch'), 4, 'synthetic-workbook', 111111100, 'D17', DATE '2026-01-01', 'draft-preview-4', decode(repeat('55', 32), 'hex'), '{}'::jsonb, 'actual_detail', 'expense', 100, true, (SELECT id FROM pg_temp.planning_ids WHERE name = 'row'))$sql$, 'Several draft previews can review the same predecessor without consuming it');
